const message = $json.message ?? {};

return {
  json: {
    chat_id: message.chat?.id ?? null,
    is_done: message.text?.trim().toLowerCase() === '/done',
    message_type: message.document ? 'resume' : 'text'
  }
};

const data = $input.first().json;

const svg = data.summary_svg;

if (!svg) {
  throw new Error('summary_svg is missing');
}

const cleanSvg = svg
  .replace(/^\uFEFF/, '')
  .trim();

if (!cleanSvg.startsWith('<svg')) {
  throw new Error('Invalid SVG: opening <svg> tag not found');
}

if (!cleanSvg.endsWith('</svg>')) {
  throw new Error('Invalid SVG: closing </svg> tag not found');
}

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(cleanSvg, 'utf8'),
  'resume-screening-summary.svg',
  'image/svg+xml'
);

return [
  {
    json: {
      ...data
    },
    binary: {
      data: binaryData
    }
  }
];

const item = $input.first();
const prepare = $('Telegram - Prepare Resume').first();

const resumeText = item.json.text || '';

const lines = resumeText
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0);

// Common resume section headings that are NOT names
const excludedHeadings = new Set([
  'EDUCATION',
  'CONTACT',
  'CONTACT INFORMATION',
  'WORK EXPERIENCE',
  'EXPERIENCE',
  'PROFESSIONAL EXPERIENCE',
  'SKILLS',
  'SUMMARY',
  'PROFESSIONAL SUMMARY',
  'PROFILE',
  'OBJECTIVE',
  'CERTIFICATIONS',
  'PROJECTS',
  'LANGUAGES',
  'REFERENCES',
  'ACHIEVEMENTS',
  'INTERESTS',
  'ABOUT ME'
]);

function looksLikeName(line) {
  const normalized = line
    .replace(/[|•·]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!normalized) return false;

  // Reject obvious section headings
  if (excludedHeadings.has(normalized.toUpperCase())) {
    return false;
  }

  // Reject lines that are mostly contact information
  if (/@|https?:\/\/|www\.|linkedin|github|\.com\b|\+?\d[\d\s().-]{6,}/i.test(normalized)) {
    return false;
  }

  // Reject very long lines
  if (normalized.length > 60) {
    return false;
  }

  // A likely name should contain mostly letters/spaces
  const letters = (normalized.match(/[A-Za-zÀ-ÿ]/g) || []).length;
  const digits = (normalized.match(/\d/g) || []).length;

  if (letters < 3 || digits > 0) {
    return false;
  }

  // Usually 2–5 words
  const words = normalized.split(/\s+/);

  if (words.length < 2 || words.length > 5) {
    return false;
  }

  return true;
}

// Search the first 20 meaningful lines for a likely candidate name
let candidateName = null;

for (const line of lines.slice(0, 20)) {
  if (looksLikeName(line)) {
    candidateName = line;
    break;
  }
}

// Fallback: keep the first line only if nothing better was found
if (!candidateName) {
  candidateName = lines[0] || null;
}

return [
  {
    json: {
      chat_id: $('Telegram Trigger').first().json.message.chat.id,
      candidate_name: candidateName,
      resume_text: resumeText,
      job_description: prepare.json.job_description
    }
  }
];

const items = $input.all();

const resumes = items.map(item => ({
  candidate_name: item.json.candidate_name,
  resume_text: item.json.resume_text
}));

return [
  {
    json: {
      job_description: items[0]?.json.job_description ?? null,
      resumes
    }
  }
];

