const raw = $json.text;

let data;

try {
  data = JSON.parse(raw);
} catch (error) {
  throw new Error('AI returned invalid JSON.');
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function assert(condition, message) {
  if (!condition) {
    throw new Error(`Resume evaluation validation failed: ${message}`);
  }
}

assert(isObject(data), 'Output must be a JSON object.');

const source = $('Loop Through Resumes').item.json;
const jobCriteria = source.job_criteria;

assert(
  isObject(jobCriteria),
  'Original job criteria could not be found.'
);

assert(
  typeof data.candidate_name === 'string',
  'candidate_name must be a string.'
);

// Prefer the AI-extracted candidate name, with workflow source as fallback.
data.candidate_name = data.candidate_name?.trim() || source.candidate_name;

// ==================================================
// ORIGINAL JD CRITERIA
// ==================================================

const mustHave = Array.isArray(jobCriteria.must_have_skills)
  ? jobCriteria.must_have_skills
  : [];

const niceToHave = Array.isArray(jobCriteria.nice_to_have_skills)
  ? jobCriteria.nice_to_have_skills
  : [];

const softSkills = Array.isArray(jobCriteria.soft_skills)
  ? jobCriteria.soft_skills
  : [];

const industryCriteria = Array.isArray(jobCriteria.industry)
  ? jobCriteria.industry
  : [];

const locationCriteria = Array.isArray(jobCriteria.location_or_timezone)
  ? jobCriteria.location_or_timezone
  : [];

// ==================================================
// HELPERS
// ==================================================

function getEvidence(array, criterion) {
  if (!Array.isArray(array)) return null;

  return (
    array.find(
      item =>
        item &&
        typeof item.criterion === 'string' &&
        item.criterion.trim() === criterion.trim()
    ) || null
  );
}

function normalizeStatus(evidence) {
  return evidence?.status ?? 'unsupported';
}

// ==================================================
// SPECIAL NORMALIZATION
// ==================================================

function normalizeMustHaveCriterion(criterion, evidence) {

  // EXPERIENCE
  if (
    criterion ===
    '1+ year of SDR or high-volume outbound sales experience'
  ) {
    if (
      data.experience &&
      typeof data.experience.candidate_years === 'number' &&
      data.experience.candidate_years >= 1
    ) {
      return 'supported';
    }

    return normalizeStatus(evidence);
  }

  // CALL VOLUME
  if (
    criterion ===
    'Proven ability to make 130–150+ calls per day while maintaining quality conversations'
  ) {
    const text = evidence?.evidence || '';

    const hasCallNumber =
      /\b\d+\+?\s*(?:outbound\s+)?calls?\s*(?:per\s*day|\/\s*day|daily|each\s+day)\b/i.test(
        text
      );

    if (hasCallNumber) {
      return normalizeStatus(evidence);
    }

    return 'unsupported';
  }

  // CRM
  if (
    criterion ===
    'Experience using Salesforce or similar CRM platforms'
  ) {
    const text = evidence?.evidence || '';

    const namedCRM =
      /\b(?:Salesforce|HubSpot|Zoho(?:\s+CRM)?|Pipedrive|Microsoft\s+Dynamics|AmoCRM)\b/i.test(
        text
      );

    if (namedCRM) {
      return 'supported';
    }

    return normalizeStatus(evidence);
  }

  return normalizeStatus(evidence);
}

// ==================================================
// CRITERIA CLASSIFIER
// ==================================================

function classifyCriteria(
  evidenceArray,
  originalCriteria,
  customNormalizer = null
) {
  assert(
    Array.isArray(evidenceArray),
    'Evidence criteria group must be an array.'
  );

  const supported = [];
  const partial = [];
  const notMentioned = [];

  for (const criterion of originalCriteria) {
    const evidence = getEvidence(
      evidenceArray,
      criterion
    );

    const status = customNormalizer
      ? customNormalizer(criterion, evidence)
      : normalizeStatus(evidence);

    if (status === 'supported') {
      supported.push(criterion);
    } else if (status === 'partial') {
      partial.push(criterion);
    } else {
      notMentioned.push(criterion);
    }
  }

  return {
    supported,
    partial,
    not_mentioned: notMentioned
  };
}

// ==================================================
// INDUSTRY
// ==================================================

const industryResult = classifyCriteria(
  data.industry,
  industryCriteria
);

// ==================================================
// MUST-HAVE
// ==================================================

const mustHaveResult = classifyCriteria(
  data.must_have,
  mustHave,
  normalizeMustHaveCriterion
);

// ==================================================
// NICE-TO-HAVE
// ==================================================

function normalizeNiceToHaveCriterion(criterion, evidence) {
  const text = evidence?.evidence || '';

  if (
    criterion ===
    'Experience with Dialpad or cloud-based calling platforms'
  ) {
    const callingPlatform =
      /\b(?:Dialpad|Aircall|CallGear|RingCentral|CloudTalk|Twilio|Five9)\b/i.test(
        text
      );

    if (callingPlatform) {
      return 'supported';
    }

    return normalizeStatus(evidence);
  }

  return normalizeStatus(evidence);
}

const niceToHaveResult = classifyCriteria(
  data.nice_to_have,
  niceToHave,
  normalizeNiceToHaveCriterion
);

// ==================================================
// SOFT SKILLS
// ==================================================

const softSkillsResult = classifyCriteria(
  data.soft_skills,
  softSkills
);

// ==================================================
// LOCATION / TIMEZONE
// ==================================================

const locationResult = classifyCriteria(
  data.location_or_timezone,
  locationCriteria
);

// ==================================================
// NORMALIZED OUTPUT
// ==================================================

data.industry = {
  required: industryCriteria,
  supported: industryResult.supported,
  partial: industryResult.partial,
  not_mentioned: industryResult.not_mentioned
};

data.must_have = {
  supported: mustHaveResult.supported,
  partial: mustHaveResult.partial,
  not_mentioned: mustHaveResult.not_mentioned
};

data.nice_to_have = {
  supported: niceToHaveResult.supported,
  partial: niceToHaveResult.partial,
  not_mentioned: niceToHaveResult.not_mentioned
};

data.soft_skills = {
  supported: softSkillsResult.supported,
  partial: softSkillsResult.partial,
  not_mentioned: softSkillsResult.not_mentioned
};

data.location_or_timezone = {
  required: locationCriteria,
  supported: locationResult.supported,
  partial: locationResult.partial,
  not_mentioned: locationResult.not_mentioned
};

// ==================================================
// EXPERIENCE
// ==================================================

assert(
  isObject(data.experience),
  'experience must be an object.'
);

const requiredYears =
  jobCriteria.required_experience_years ?? null;

const candidateYears =
  typeof data.experience.candidate_years === 'number'
    ? data.experience.candidate_years
    : null;

data.experience = {
  required_years: requiredYears,
  candidate_years: candidateYears,
  evidence: data.experience.evidence ?? '',
  meets_requirement:
    requiredYears === null || candidateYears === null
      ? null
      : candidateYears >= requiredYears
};

// ==================================================
// SENIORITY
// ==================================================

assert(
  isObject(data.seniority),
  'seniority must be an object.'
);

const requiredSeniority =
  jobCriteria.seniority ?? null;

const candidateSeniority =
  data.seniority.candidate ?? null;

data.seniority = {
  required: requiredSeniority,
  candidate: candidateSeniority,
  meets_requirement:
    requiredSeniority === null
      ? null
      : data.seniority.status === 'supported'
};

// ==================================================
// SCREENING QUESTION
// ==================================================

function buildScreeningQuestion() {

  if (mustHaveResult.not_mentioned.length > 0) {
    const criterion =
      mustHaveResult.not_mentioned[0];

    return `Can you walk us through your experience with "${criterion}" and provide a specific example?`;
  }

  if (mustHaveResult.partial.length > 0) {
    const criterion =
      mustHaveResult.partial[0];

    return `Can you provide more specific evidence of your experience with "${criterion}"?`;
  }

  if (locationResult.not_mentioned.length > 0) {
    const criterion =
      locationResult.not_mentioned[0];

    return `Are you comfortable meeting the required working schedule: "${criterion}"?`;
  }

  if (niceToHaveResult.not_mentioned.length > 0) {
    const criterion =
      niceToHaveResult.not_mentioned[0];

    return `Can you tell us whether you have experience with "${criterion}"?`;
  }

  return 'Can you walk us through the experience in your resume that is most relevant to this role?';
}

data.screening_question =
  buildScreeningQuestion();

// ==================================================
// REASONING
// ==================================================

function buildReasoning() {

  const supported =
    mustHaveResult.supported.length;

  const partial =
    mustHaveResult.partial.length;

  const missing =
    mustHaveResult.not_mentioned.length;

  let experienceText;

  if (data.experience.meets_requirement === true) {
    experienceText =
      `${data.experience.candidate_years}+ years of relevant experience`;
  } else if (
    data.experience.meets_requirement === false
  ) {
    experienceText =
      `${data.experience.candidate_years ?? 0} years of relevant experience`;
  } else {
    experienceText =
      'the required experience level could not be fully verified';
  }

  let sentence1 =
    `The resume provides explicit evidence for ${supported} of ${mustHave.length} required criteria, with ${partial} additional criteria partially supported, and indicates ${experienceText}.`;

  let sentence2;

  if (missing > 0) {
    sentence2 =
      `The main gap is ${mustHaveResult.not_mentioned.slice(0, 2).join(' and ')}.`;
  } else {
    sentence2 =
      'No major required-criterion gaps were identified from the available resume evidence.';
  }

  return `${sentence1} ${sentence2}`;
}

data.reasoning =
  buildReasoning();

// ==================================================
// VALIDATION
// ==================================================

function validateCriteria(
  original,
  supported,
  partial,
  notMentioned,
  label
) {
  const all = [
    ...supported,
    ...partial,
    ...notMentioned
  ];

  for (const criterion of original) {
    const count =
      all.filter(item => item === criterion).length;

    assert(
      count === 1,
      `${label} criterion must appear exactly once: "${criterion}"`
    );
  }

  for (const criterion of all) {
    assert(
      original.includes(criterion),
      `Invented or altered ${label} criterion: "${criterion}"`
    );
  }

  assert(
    new Set(all).size === all.length,
    `Duplicate ${label} criteria detected.`
  );
}

validateCriteria(
  industryCriteria,
  data.industry.supported,
  data.industry.partial,
  data.industry.not_mentioned,
  'industry'
);

validateCriteria(
  mustHave,
  data.must_have.supported,
  data.must_have.partial,
  data.must_have.not_mentioned,
  'must-have'
);

validateCriteria(
  niceToHave,
  data.nice_to_have.supported,
  data.nice_to_have.partial,
  data.nice_to_have.not_mentioned,
  'nice-to-have'
);

validateCriteria(
  softSkills,
  data.soft_skills.supported,
  data.soft_skills.partial,
  data.soft_skills.not_mentioned,
  'soft-skills'
);

validateCriteria(
  locationCriteria,
  data.location_or_timezone.supported,
  data.location_or_timezone.partial,
  data.location_or_timezone.not_mentioned,
  'location/timezone'
);

assert(
  typeof data.reasoning === 'string' &&
  data.reasoning.trim().length > 0,
  'reasoning must be a non-empty string.'
);

assert(
  typeof data.screening_question === 'string' &&
  data.screening_question.trim().length > 0,
  'screening_question must be a non-empty string.'
);

return [
  {
    json: data
  }
];

const candidate = $json;

// These weights are our scoring design choices.
// They are NOT specified by the exercise file.
const WEIGHTS = {
  must_have: 50,
  experience: 20,
  seniority: 10,
  industry: 5,
  location_or_timezone: 5,
  nice_to_have: 5,
  soft_skills: 5
};

// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function round(value) {
  return Math.round(value * 100) / 100;
}

function weightedCriteriaScore(group, weight, excludedCriteria = []) {
  if (!group) return null;

  const excluded = new Set(excludedCriteria);

  const supported = Array.isArray(group.supported)
    ? group.supported.filter(item => !excluded.has(item)).length
    : 0;

  const partial = Array.isArray(group.partial)
    ? group.partial.filter(item => !excluded.has(item)).length
    : 0;

  const notMentioned = Array.isArray(group.not_mentioned)
    ? group.not_mentioned.filter(item => !excluded.has(item)).length
    : 0;

  const total =
    supported +
    partial +
    notMentioned;

  if (total === 0) return null;

  // Supported = 100%
  // Partial = 50%
  // Not mentioned = 0%
  const earnedEquivalent =
    supported +
    (partial * 0.5);

  return round(
    (earnedEquivalent / total) * weight
  );
}

let earnedScore = 0;
let applicableWeight = 0;

const scoreBreakdown = {};

// ------------------------------------
// 1. MUST-HAVE SKILLS
// ------------------------------------

// Experience is scored separately below,
// so exclude the experience criterion here.
const EXPERIENCE_CRITERION =
  '1+ year of SDR or high-volume outbound sales experience';

const mustHaveScore =
  weightedCriteriaScore(
    candidate.must_have,
    WEIGHTS.must_have,
    [EXPERIENCE_CRITERION]
  );

if (mustHaveScore !== null) {
  scoreBreakdown.must_have = mustHaveScore;

  earnedScore += mustHaveScore;
  applicableWeight += WEIGHTS.must_have;
}

// ------------------------------------
// 2. EXPERIENCE
// ------------------------------------

if (
  candidate.experience &&
  candidate.experience.meets_requirement !== null
) {

  const score =
    candidate.experience.meets_requirement === true
      ? WEIGHTS.experience
      : 0;

  scoreBreakdown.experience = score;

  earnedScore += score;
  applicableWeight += WEIGHTS.experience;
}

// ------------------------------------
// 3. SENIORITY
// ------------------------------------

if (
  candidate.seniority &&
  candidate.seniority.required !== null
) {

  const score =
    candidate.seniority.meets_requirement === true
      ? WEIGHTS.seniority
      : 0;

  scoreBreakdown.seniority = score;

  earnedScore += score;
  applicableWeight += WEIGHTS.seniority;
}

// ------------------------------------
// 4. INDUSTRY
// ------------------------------------

const industryRequired =
  Array.isArray(candidate.industry?.required)
    ? candidate.industry.required.length
    : 0;

if (industryRequired > 0) {

  const industryScore =
    weightedCriteriaScore(
      candidate.industry,
      WEIGHTS.industry
    );

  if (industryScore !== null) {
    scoreBreakdown.industry = industryScore;

    earnedScore += industryScore;
    applicableWeight += WEIGHTS.industry;
  }
}

// ------------------------------------
// 5. LOCATION / TIMEZONE
// ------------------------------------

const locationRequired =
  Array.isArray(
    candidate.location_or_timezone?.required
  )
    ? candidate.location_or_timezone.required.length
    : 0;

if (locationRequired > 0) {

  const locationScore =
    weightedCriteriaScore(
      candidate.location_or_timezone,
      WEIGHTS.location_or_timezone
    );

  if (locationScore !== null) {
    scoreBreakdown.location_or_timezone =
      locationScore;

    earnedScore += locationScore;
    applicableWeight += WEIGHTS.location_or_timezone;
  }
}

// ------------------------------------
// 6. NICE-TO-HAVE SKILLS
// ------------------------------------

const niceToHaveScore =
  weightedCriteriaScore(
    candidate.nice_to_have,
    WEIGHTS.nice_to_have
  );

if (niceToHaveScore !== null) {
  scoreBreakdown.nice_to_have =
    niceToHaveScore;

  earnedScore += niceToHaveScore;
  applicableWeight += WEIGHTS.nice_to_have;
}

// ------------------------------------
// 7. SOFT SKILLS
// ------------------------------------

const softSkillsScore =
  weightedCriteriaScore(
    candidate.soft_skills,
    WEIGHTS.soft_skills
  );

if (softSkillsScore !== null) {
  scoreBreakdown.soft_skills =
    softSkillsScore;

  earnedScore += softSkillsScore;
  applicableWeight += WEIGHTS.soft_skills;
}

// ------------------------------------
// FINAL NORMALIZED SCORE
// ------------------------------------

const fitScore =
  applicableWeight === 0
    ? 0
    : round(
        (earnedScore / applicableWeight) * 100
      );

return {
  json: {
    ...candidate,

    score_breakdown: scoreBreakdown,

    raw_score: round(earnedScore),

    applicable_weight: applicableWeight,

    fit_score: fitScore
  }
};

const candidates = $input.all();

if (!candidates.length) {
  throw new Error('No candidates received.');
}

// Remove accidental duplicate candidates
const uniqueCandidates = [];
const seen = new Set();

for (const item of candidates) {
  const candidate = item.json;

  const key = `${candidate.candidate_name}|${candidate.fit_score}`;

  if (!seen.has(key)) {
    seen.add(key);
    uniqueCandidates.push(item);
  }
}

// Sort by fit score
uniqueCandidates.sort((a, b) => {
  return Number(b.json.fit_score) - Number(a.json.fit_score);
});

// Assign rank
return uniqueCandidates.map((item, index) => ({
  json: {
    ...item.json,
    rank: index + 1
  }
}));

const candidates = $input.all();

if (!candidates.length) {
  throw new Error('Node 11 received no candidates from Node 10.');
}

const sortedCandidates = [...candidates].sort(
  (a, b) => Number(a.json.rank ?? 999) - Number(b.json.rank ?? 999)
);

return [
  {
    json: {
      job_title:
        $('Parse JD JSON').first().json.job_title ?? null,

      total_candidates: sortedCandidates.length,

      ranked_candidates: sortedCandidates.map(item => ({
        rank: item.json.rank,
        candidate_name: item.json.candidate_name,
        fit_score: item.json.fit_score,
        reasoning: item.json.reasoning,
        screening_question: item.json.screening_question
      })),

      side_by_side: sortedCandidates.map(item => ({
        rank: item.json.rank,
        candidate_name: item.json.candidate_name,
        fit_score: item.json.fit_score,

        reasoning: item.json.reasoning,
        screening_question: item.json.screening_question,

        experience: item.json.experience,
        seniority: item.json.seniority,
        industry: item.json.industry,
        must_have: item.json.must_have,
        nice_to_have: item.json.nice_to_have,
        soft_skills: item.json.soft_skills,
        location_or_timezone: item.json.location_or_timezone,
        education: item.json.education,
        certifications: item.json.certifications
      }))
    }
  }
];
